    def fmt(a, qs):
        return '%d\n%s\n%d\n%s' % (len(a), ' '.join(map(str, a)), len(qs), '\n'.join('%d %d' % x for x in qs))
    tests = [
        fmt([1], [(0, 0)]),
        fmt([0], [(0, 0), (1, 1), (0, 1)]),
        fmt([1, 0, 1, 1, 0], [(0, 4), (2, 3), (3, 2), (-1, 2), (1, 5), (4, 4), (0, 0)]),
        fmt([1, 1, 1], [(0, 2), (1, 1), (2, 0), (-5, -1), (3, 3)]),
        fmt([0, 0, 0, 0], [(0, 3), (1, 2)]),
    ]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(2):
            a = [rng.randint(0, 1) for _ in range(n)]
            qs = []
