                if rng.random() < 0.25:
                    qs.append((rng.randint(-3, n + 2), rng.randint(-3, n + 2)))
                else:
                    s = rng.randint(0, n - 1)
                    qs.append((s, rng.randint(s, n - 1)))
            tests.append(fmt(a, qs))
